import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

# Calculate f(K_n) and g(K_n)
def f_kn(n):
    # Number of triangles (K3)
    return combinations(n, 3)

def g_kn(n):
    # Number of 4-cycles (C4, "tetrahedra") in K_n. Each C4 count is 3 * C(n, 4)
    return 3 * combinations(n, 4)

# Calculate the ratio R(n) = g(K_n)^3 / f(K_n)^4
def calculate_ratio(n):
    f = f_kn(n)
    g = g_kn(n)
    if f == 0:
        return float('inf')
    return (g**3) / (f**4)

# Calculate for n=8 and n=9
ratio_8 = calculate_ratio(8)
ratio_9 = calculate_ratio(9)

print(f"R(8) = {ratio_8}")
print(f"R(9) = {ratio_9}")

